package cn.zhuatech.spc.deep;import cn.zhuatech.spc.common.ApiResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/spc-ops") public class DeepDomainController{private final DeepDomainService s;public DeepDomainController(DeepDomainService s){this.s=s;}@GetMapping("/dashboard")ApiResponse<?> dashboard(@RequestParam String organizationCode){return ApiResponse.ok(s.dashboard(organizationCode));}@PostMapping("/characteristics")ApiResponse<?> create(@Valid @RequestBody DeepDomainService.CharacteristicRequest r){return ApiResponse.ok(s.create(r));}@PostMapping("/characteristics/{id}/samples")ApiResponse<?> sample(@PathVariable Long id,@Valid @RequestBody DeepDomainService.SampleRequest r){return ApiResponse.ok(s.sample(id,r));}@PostMapping("/signals/{id}/assign")ApiResponse<?> assign(@PathVariable Long id,@Valid @RequestBody DeepDomainService.AssignRequest r){return ApiResponse.ok(s.assign(id,r));}@PostMapping("/signals/{id}/corrective-action")ApiResponse<?> corrective(@PathVariable Long id,@Valid @RequestBody DeepDomainService.CorrectiveRequest r){return ApiResponse.ok(s.corrective(id,r));}}
